dleware/dist/handlers/response-interceptor.js","node_modules/http-proxy-middleware/dist/handlers/fix-request-body.js","node_modules/ws/lib/receiver.js","node_modules/ws/lib/permessage-deflate.js","node_modules/ws/lib/buffer-util.js","node_modules/ws/lib/constants.js","node_modules/ws/lib/limiter.js","node_modules/ws/lib/validation.js","node_modules/ws/lib/sender.js","node_modules/ws/lib/stream.js","node_modules/ws/lib/websocket.js","node_modules/ws/lib/event-target.js","node_modules/ws/lib/extension.js","node_modules/ws/lib/websocket-server.js","node_modules/ws/lib/subprotocol.js","node_modules/shell-quote/quote.js","node_modules/shell-quote/parse.js","packages/reporters/dev-server/src/ServerReporter.js","packages/reporters/dev-server/src/HMRServer.js","packages/reporters/dev-server/src/Server.js","packages/reporters/dev-server/src/serverErrors.js","node_modules/ejs/lib/ejs.js","node_modules/ejs/lib/utils.js","node_modules/ejs/package.json","node_modules/connect/index.js","node_modules/finalhandler/index.js","node_modules/finalhandler/node_modules/encodeurl/index.js","node_modules/escape-html/index.js","node_modules/finalhandler/node_modules/on-finished/index.js","node_modules/ee-first/index.js","node_modules/parseurl/index.js","node_modules/finalhandler/node_modules/statuses/index.js","node_modules/finalhandler/node_modules/statuses/codes.json","node_modules/unpipe/index.js","node_modules/serve-handler/src/index.js","node_modules/serve-handler/src/glob-slash.js","node_modules/minimatch/minimatch.js","node_modules/minimatch/node_modules/brace-expansion/index.js","node_modules/concat-map/index.js","node_modules/balanced-match/index.js","node_modules/serve-handler/node_modules/path-to-regexp/index.js","node_modules/mime-types/index.js","node_modules/mime-types/node_modules/mime-db/index.js","node_modules/serve-handler/node_modules/bytes/index.js","node_modules/content-disposition/index.js","node_modules/path-is-inside/lib/path-is-inside.js","node_modules/serve-handler/node_modules/range-parser/index.js","node_modules/serve-handler/src/directory.js","node_modules/serve-handler/src/error.js","node_modules/http-proxy-middleware/dist/index.js","node_modules/http-proxy-middleware/dist/http-proxy-middleware.js","node_modules/http-proxy/index.js","node_modules/http-proxy-middleware/dist/config-factory.js","node_modules/http-proxy-middleware/node_modules/is-plain-obj/index.js","node_modules/http-proxy-middleware/dist/errors.js","node_modules/http-proxy-middleware/dist/logger.js","node_modules/http-proxy-middleware/dist/context-matcher.js","node_modules/is-glob/index.js","node_modules/is-extglob/index.js","node_modules/micromatch/index.js","node_modules/braces/index.js","node_modules/braces/lib/stringify.js","node_modules/braces/lib/utils.js","node_modules/braces/lib/compile.js","node_modules/fill-range/index.js","node_modules/to-regex-range/index.js","node_modules/to-regex-range/node_modules/is-number/index.js","node_modules/braces/lib/expand.js","node_modules/braces/lib/parse.js","node_modules/braces/lib/constants.js","node_modules/picomatch/index.js","node_modules/http-proxy-middleware/dist/_handlers.js","node_modules/http-proxy-middleware/dist/path-rewriter.js","node_modules/http-proxy-middleware/dist/router.js","node_modules/fresh/index.js","node_modules/nullthrows/nullthrows.js","node_modules/ws/index.js","node_modules/launch-editor/index.js","node_modules/picocolors/picocolors.js","node_modules/launch-editor/guess.js","node_modules/shell-quote/index.js","node_modules/launch-editor/editor-info/macos.js","node_modules/launch-editor/editor-info/linux.js","node_modules/launch-editor/editor-info/windows.js","node_modules/launch-editor/get-args.js","packages/reporters/dev-server/src/NodeRunner.js","packages/core/diagnostic/src/diagnostic.js","node_modules/@mischnic/json-sourcemap/dist/index.js","node_modules/@lezer/common/dist/index.js","node_modules/json5/dist/index.mjs","node_modules/@lezer/lr/dist/index.js"],"sourcesContent":["/**\n * Detect Electron renderer process, which is node, but we should\n * treat as a browser.\n */\n\nif (typeof process !== 'undefined' && process.type === 'renderer') {\n  module.exports = require('./browser.js');\n} else {\n  module.exports = require('./node.js');\n}\n","/**\n * This is the web browser implementation of `debug()`.\n *\n * Expose `debug()` as the module.\n */\n\nexports = module.exports = require('./debug');\nexports.log = log;\nexports.formatArgs = formatArgs;\nexports.save = save;\nexports.load = load;\nexports.useColors = useColors;\nexports.storage = 'undefined' != typeof chrome\n               && 'undefined' != typeof chrome.storage\n                  ? chrome.storage.local\n                  : localstorage();\n\n/**\n * Colors.\n */\n\nexports.colors = [\n  'lightseagreen',\n  'forestgreen',\n  'goldenrod',\n  'dodgerblue',\n  'darkorchid',\n  'crimson'\n];\n\n/**\n * Currently only WebKit-based Web Inspectors, Firefox >= v31,\n * and the Firebug extension (any Firefox version) are known\n * to support \"%c\" CSS customizations.\n *\n * TODO: add a `localStorage` variable to explicitly enable/disable colors\n */\n\nfunction useColors() {\n  // NB: In an Electron preload script, document will be defined but not fully\n  // initialized. Since we know we're in Chrome, we'll just detect this case\n  // explicitly\n  if (typeof window !== 'undefined' && window.process && window.process.type === 'renderer') {\n    return true;\n  }\n\n  // is webkit? http://stackoverflow.com/a/16459606/376773\n  // document is undefined in react-native: https://github.com/facebook/react-native/pull/1632\n  return (typeof document !== 'undefined' && document.documentElement && document.documentElement.style && document.documentElement.style.WebkitAppearance) ||\n    // is firebug? http://stackoverflow.com/a/398120/376773\n    (typeof window !== 'undefined' && window.console && (window.console.firebug || (window.console.exception && window.console.table))) ||\n    // is firefox >= v31?\n    // https://developer.mozilla.org/en-US/docs/Tools/Web_Console#Styling_messages\n    (typeof navigator !== 'undefined' && navigator.userAgent && navigator.userAgent.toLowerCase().match(/firefox\\/(\\d+)/) && parseInt(RegExp.$1, 10) >= 31) ||\n    // double check webkit in userAgent just in case we are in a worker\n    (typeof navigator !== 'undefined' && navigator.userAgent && navigator.userAgent.toLowerCase().match(/applewebkit\\/(\\d+)/));\n}\n\n/**\n * Map %j to `JSON.stringify()`, since no Web Inspectors do that by default.\n */\n\nexports.formatters.j = function(v) {\n  try {\n    return JSON.stringify(v);\n  } catch (err) {\n    return '[UnexpectedJSONParseError]: ' + err.message;\n  }\n};\n\n\n/**\n * Colorize log arguments if enabled.\n *\n * @api public\n */\n\nfunction formatArgs(args) {\n  var useColors = this.useColors;\n\n  args[0] = (useColors ? '%c' : '')\n    + this.namespace\n    + (useColors ? ' %c' : ' ')\n    + args[0]\n    + (useColors ? '%c ' : ' ')\n    + '+' + exports.humanize(this.diff);\n\n  if (!useColors) return;\n\n  var c = 'color: ' + this.color;\n  args.splice(1, 0, c, 'color: inherit')\n\n  // the final \"%c\" is somewhat tricky, because there could be other\n  // arguments passed either before or after the %c, so we need to\n  // figure out the correct index to insert the CSS into\n  var index = 0;\n  var lastC = 0;\n  args[0].replace(/%[a-zA-Z%]/g, function(match) {\n    if ('%%' === match) return;\n    index++;\n    if ('%c' === match) {\n      // we only are interested in the *last* %c\n      // (the user may have provided their own)\n      lastC = index;\n    }\n  });\n\n  args.splice(lastC, 0, c);\n}\n\n/**\n * Invokes `console.log()` when available.\n * No-op when `console.log` is not a \"function\".\n *\n * @api public\n */\n\nfunction log() {\n  // this hackery is required for IE8/9, where\n  // the `console.log` function doesn't have 'apply'\n  return 'object' === typeof console\n    && console.log\n    && Function.prototype.apply.call(console.log, console, arguments);\n}\n\n/**\n * Save `namespaces`.\n *\n * @param {String} namespaces\n * @api private\n */\n\nfunction save(namespaces) {\n  try {\n    if (null == namespaces) {\n      exports.storage.removeItem('debug');\n    } else {\n      exports.storage.debug = namespaces;\n    }\n  } catch(e) {}\n}\n\n/**\n * Load `namespaces`.\n *\n * @return {String} returns the previously persisted debug modes\n * @api private\n */\n\nfunction load() {\n  var r;\n  try {\n    r = exports.storage.debug;\n  } catch(e) {}\n\n  // If debug isn't set in LS, and we're in Electron, try to load $DEBUG\n  if (!r && typeof process !== 'undefined' && 'env' in process) {\n    r = process.env.DEBUG;\n  }\n\n  return r;\n}\n\n/**\n * Enable namespaces listed in `localStorage.debug` initially.\n */\n\nexports.enable(load());\n\n/**\n * Localstorage attempts to return the localstorage.\n *\n * This is necessary because safari throws\n * when a user disables cookies/localstorage\n * and you attempt to access it.\n *\n * @return {LocalStorage}\n * @api private\n */\n\nfunction localstorage() {\n  try {\n    return window.localStorage;\n  } catch (e) {}\n}\n","\n/**\n * This is the common logic for both the Node.js and web browser\n * implementations of `debug()`.\n *\n * Expose `debug()` as the module.\n */\n\nexports = module.exports = createDebug.debug = createDebug['default'] = createDebug;\nexports.coerce = coerce;\nexports.disable = disable;\nexports.enable = enable;\nexports.enabled = enabled;\nexports.humanize = require('ms');\n\n/**\n * The currently active debug mode names, and names to skip.\n */\n\nexports.names = [];\nexports.skips = [];\n\n/**\n * Map of special \"%n\" handling functions, for the debug \"format\" argument.\n *\n * Valid key names are a single, lower or upper-case letter, i.e. \"n\" and \"N\".\n */\n\nexports.formatters = {};\n\n/**\n * Previous log timestamp.\n */\n\nvar prevTime;\n\n/**\n * Select a color.\n * @param {String} namespace\n * @return {Number}\n * @api private\n */\n\nfunction selectColor(namespace) {\n  var hash = 0, i;\n\n  for (i in namespace) {\n    hash  = ((hash << 5) - hash) + namespace.charCodeAt(i);\n    hash |= 0; // Convert to 32bit integer\n  }\n\n  return exports.colors[Math.abs(hash) % exports.colors.length];\n}\n\n/**\n * Create a debugger with the given `namespace`.\n *\n * @param {String} namespace\n * @return {Function}\n * @api public\n */\n\nfunction createDebug(namespace) {\n\n  function debug() {\n    // disabled?\n    if (!debug.enabled) return;\n\n    var self = debug;\n\n    // set `diff` timestamp\n    var curr = +new Date();\n    var ms = curr - (prevTime || curr);\n    self.diff = ms;\n    self.prev = prevTime;\n    self.curr = curr;\n    prevTime = curr;\n\n    // turn the `arguments` into a proper Array\n    var args = new Array(arguments.length);\n    for (var i = 0; i < args.length; i++) {\n      args[i] = arguments[i];\n    }\n\n    args[0] = exports.coerce(args[0]);\n\n    if ('string' !== typeof args[0]) {\n      // anything else let's inspect with %O\n      args.unshift('%O');\n    }\n\n    // apply any `formatters` transformations\n    var index = 0;\n    args[0] = args[0].replace(/%([a-zA-Z%])/g, function(match, format) {\n      // if we encounter an escaped % then don't increase the array index\n      if (match === '%%') return match;\n      index++;\n      var formatter = exports.formatters[format];\n      if ('function' === typeof formatter) {\n        var val = args[index];\n        match = formatter.call(self, val);\n\n        // now we need to remove `args[index]` since it's inlined in the `format`\n        args.splice(index, 1);\n        index--;\n      }\n      return match;\n    });\n\n    // apply env-specific formatting (colors, etc.)\n    exports.formatArgs.call(self, args);\n\n    var logFn = debug.log || exports.log || console.log.bind(console);\n    logFn.apply(self, args);\n  }\n\n  debug.namespace = namesp